<script setup lang="ts">
import { computed } from 'vue'
import { useExperimentStore, useSystemStore, useTradeStore, useInterfaceStore } from '../../stores'
import { money } from '../../format'
import StatusBadge from '../../components/StatusBadge.vue'
const ui = useInterfaceStore(); const experiments = useExperimentStore(); const system = useSystemStore(); const trades = useTradeStore()
const active = computed(() => experiments.experiments.find(e => e.id === ui.profile))
const state = computed(() => system.error ? 'DATA_UNAVAILABLE · evidencia conservada STALE.' : system.connection !== 'CONNECTED' ? 'Conexión interrumpida; evidencia conservada STALE.' : trades.open.length ? 'Hay inventario bajo observación. Verifica su procedencia.' : system.studyStatus === 'SHADOW_RESEARCH_RUNNING' ? 'TradingAgent está observando oportunidades Shadow.' : system.studyStatus)
</script>
<template><section class="card account-card" data-testid="account-card"><div class="panel-heading"><span class="eyebrow">EXPERIMENTAL ACCOUNT · {{ ui.profile }}</span><StatusBadge :value="system.error||system.connection!=='CONNECTED'?'SIMULATED_SHADOW · STALE':'SIMULATED_SHADOW'" tone="neutral" /></div><label for="account-profile" class="sr-only">Cartera mostrada</label><select id="account-profile" v-model="ui.profile"><option v-for="e in experiments.experiments" :key="e.id" :value="e.id">{{ e.id }}</option></select><p class="account-caption">Equity virtual · USD</p><strong class="account-balance">{{ active?.metrics ? money(active.metrics.equity) : 'DATA_UNAVAILABLE' }}</strong><div class="account-metrics"><div><span>Capital disponible</span><b class="unknown-metric">DATA_UNAVAILABLE</b><small>Reservas Shadow no expuestas</small></div><div><span>Capital experimental</span><b>{{ active?.metrics ? money(active.metrics.initialCapital) : 'DATA_UNAVAILABLE' }}</b></div><div><span>P&L total realizado</span><b :class="{'positive':(active?.metrics?.netPnl ?? 0)>0,'negative':(active?.metrics?.netPnl ?? 0)<0}">{{ active?.metrics ? money(active.metrics.netPnl) : 'DATA_UNAVAILABLE' }}</b></div><div><span>P&L sesión</span><b>DATA_UNAVAILABLE</b><small>Sin métrica de sesión expuesta</small></div><div><span>Drawdown actual</span><b>{{ active?.metrics ? money(active.metrics.currentDrawdown) : 'DATA_UNAVAILABLE' }}</b></div><div><span>Riesgo previsto</span><b>{{ money(active?.risk?.nextBudget) }}</b></div></div><p class="agent-state"><span class="connection-dot" :class="{online:system.connection==='CONNECTED'}"></span>{{ state }}</p><details class="account-provenance"><summary>Capital y procedencia</summary><p>No es el saldo de IBKR. Cada cartera conserva su propio capital; no se suman R1/R5/R10. Balance de efectivo y reservas Shadow: DATA_UNAVAILABLE. P&amp;L sesión: DATA_UNAVAILABLE, sin métrica expuesta.</p></details></section></template>
